        { subject: "CDP", type: "Pedagogy", tagText: "Peer Learning", question: "मुले जेव्हा एकमेकांच्या मदतीने गटात शिकतात, तेव्हा त्यास काय म्हणतात?", options: ["एकल अध्ययन", "सहअध्ययन / सहकार्यात्मक अध्ययन (Peer Learning)", "पाठांतर", "कडक स्पर्धा"], answer: 1, explanation: "समान वयाच्या मित्रांसोबत चर्चेतून शिकल्याने सहकार्य व आत्मविश्वास वाढतो." },
        { subject: "Marathi", type: "Vakprachar", tagText: "Vocab", question: "'तोंडावर बोट ठेवणे' या वाक्प्रचाराचा अर्थ काय?", options: ["शांत बसणे (गप्प राहणे)", "जेवणे", "हात धुणे", "रडणे"], answer: 0, explanation: "आश्चर्याने किंवा भीतीपोटी पूर्णपणे शांत बसणे म्हणजे तोंडावर बोट ठेवणे." },
        { subject: "Marathi", type: "Samas", tagText: "Grammar", question: "'आईवडील' या शब्दाचा समास ओळखा.", options: ["इतरतर द्वंद्व समास", "कर्मधारय", "द्विगु", "बहुव्रीही"], answer: 0, explanation: "आई आणि वडील असे दोन्ही पदे समान महत्त्वाचे असल्याने इतरतर द्वंद्व समास." },
        { subject: "Marathi", type: "Sandhi", tagText: "Grammar", question: "'देवालय' या शब्दाचा संधी विग्रह सांगा.", options: ["देव + आलय", "देवा + लय", "देव + लय", "देवे + आलय"], answer: 0, explanation: "देव + आलय = देवालय (सजातीय स्वर संधी)." },
        { subject: "Marathi", type: "Vakya", tagText: "Grammar", question: "'तो शाळेत गेला आणि त्याने अभ्यास केला.' - हे कोणते वाक्य आहे?", options: ["केवळ वाक्य", "संयुक्त वाक्य", "मिश्र वाक्य", "नकारार्थी"], answer: 1, explanation: "'आणि' या समुच्चयबोधक अव्ययाने जोडल्यामुळे हे संयुक्त वाक्य आहे." },
        { subject: "English", type: "Preposition", tagText: "Grammar", question: "Fill in the blank: 'He was born ____ Mumbai.'", options: ["at", "in", "on", "to"], answer: 1, explanation: "For large cities or countries, preposition 'in' is used." },
        { subject: "English", type: "Voice", tagText: "Grammar", question: "Passive form of: 'She writes a letter.'", options: ["A letter writes by her.", "A letter is written by her.", "A letter was written by her.", "A letter has written."], answer: 1, explanation: "Simple present passive: is/are + V3 -> 'is written by her'." },
        { subject: "English", type: "Clauses", tagText: "Grammar", question: "Identify clause type: 'I know the girl *who won the race*.'", options: ["Noun clause", "Adjective clause", "Adverb clause", "None"], answer: 1, explanation: "It qualifies the noun 'girl', hence an Adjective clause." },
        { subject: "English", type: "Reading", tagText: "Pedagogy", question: "Reading silently without vocal movement helps in developing:", options: ["Fast reading speed & comprehension", "Loud pronunciation", "Speech drills", "Spelling memory"], answer: 0, explanation: "Silent reading increases reading rate and cognitive comprehension." },
        { subject: "Maths", type: "Mensuration", tagText: "Perimeter", question: "आयताची परिमिती काढण्याचे सूत्र कोणते?", options: ["लांबी × रुंदी", "2 × (लांबी + रुंदी)", "4 × बाजू", "बाजू²"], answer: 1, explanation: "आयताची परिमिती = 2 × (लांबी + रुंदी)." },
        { subject: "Maths", type: "Arithmetic", tagText: "Fractions", question: "1/2 + 1/2 बरोबर किती?", options: ["1/4", "1", "2/4", "2"], answer: 1, explanation: "अर्धा + अर्धा = 1 (2/2 = 1)." },
        { subject: "Maths", type: "Arithmetic", tagText: "Multiply", question: "25 × 4 बरोबर किती?", options: ["50", "75", "100", "125"], answer: 2, explanation: "25 × 4 = 100." },
        { subject: "Maths", type: "Geometry", tagText: "Shapes", question: "4 बाजू आणि 4 काटकोन असणाऱ्या समभुज आकृतीला काय म्हणतात?", options: ["आयत", "चौरस (Square)", "त्रिकोण", "वर्तुळ"], answer: 1, explanation: "चारही बाजू समान आणि सर्व कोन काटकोन असणारा चौकोन म्हणजे चौरस." },
        { subject: "EVS", type: "Agriculture", tagText: "Vermicompost", question: "गांडूळ खताला शेतकऱ्यांचा मित्र का म्हटले जाते?", options: ["ते पिके खाऊन टाकतात", "ते जमिनीची सुपीकता व सेंद्रिय घटक वाढवतात", "ते पाणी कमी करतात", "ते विषारी असतात"], answer: 1, explanation: "गांडूळ सेंद्रिय कचऱ्याचे विघटन करून जमिनीला अतिशय पोषक खत पुरवतो." },
        { subject: "EVS", type: "Water", tagText: "Stepwells", question: "महाराष्ट्रातील ऐतिहासिक 'बारव' म्हणजे काय?", options: ["दगडी पायऱ्यांची विहीर", "मातीचे धरण", "नदीचा प्रवाह", "तळे"], answer: 0, explanation: "पाणी साठवण्यासाठी दगडी पायऱ्यांनी बांधलेली पारंपरिक विहीर म्हणजे बारव." },
        { subject: "EVS", type: "Astronomy", tagText: "Sun", question: "पृथ्वीला उष्णता आणि प्रकाशाचा मुख्य नैसर्गिक स्रोत कोणता?", options: ["चंद्र", "सूर्य (Sun)", "तारे", "विद्युत"], answer: 1, explanation: "सूर्य हा आपल्या सूर्यमालेचा केंद्रबिंदू आणि पृथ्वीवरील सर्व ऊर्जेचा मुख्य स्रोत आहे." },
        { subject: "EVS", type: "Geography", tagText: "Rivers", question: "भारतातील सर्वात पवित्र व राष्ट्रीय नदी म्हणून कोणती नदी ओळखली जाते?", options: ["यमुना", "गंगा (Ganga)", "गोदावरी", "नर्मदा"], answer: 1, explanation: "गंगा ही भारताची राष्ट्रीय नदी असून सर्वात विस्तीर्ण जलप्रणाली आहे." }
